SELECT to_user_id AS toUserId, created_at AS createdAt
FROM following
WHERE from_user_id=#{fromUserId}
  AND rel_status=1
  AND (
        #{cursorCreatedAt} IS NULL
        OR created_at < #{cursorCreatedAt}
        OR (created_at = #{cursorCreatedAt} AND to_user_id < #{cursorToUserId})
      )
ORDER BY created_at DESC, to_user_id DESC
LIMIT #{limit}

SELECT from_user_id AS fromUserId, created_at AS createdAt
FROM following
WHERE to_user_id=#{toUserId}
